function notifyDataChanged() {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('contentmate-data-changed'));
  }
}

const db = {
  // PROFILE
  async getProfile() {
    return performTx('profile', 'readonly', (store) => {
      return new Promise((resolve) => {
        const req = store.get('doctor_profile');
        // Merge defaults so older workspaces receive newly introduced defaults.
        req.onsuccess = () => {
          if (!req.result) {
            resolve({ ...defaultDoctorProfile, onboarded: false });
            return;
          }
          // Version 2 replaces the old one-post, Mon/Wed/Fri sprinkle with
          // the compact daily batch scheduler. Later changes remain entirely
          // user-controlled through Settings.
          const isLegacySchedule = !req.result.schedulerVersion;
          resolve({
            ...defaultDoctorProfile,
            ...req.result,
            ...(isLegacySchedule ? { postingDays: ['Daily'], maxPostsPerDay: 3, schedulerVersion: 2 } : {})
          });
        };
        req.onerror = () => reject(req.error || new Error('Could not read the workspace profile.'));
      });
    });
  },

  async saveProfile(profile) {
    const res = await performTx('profile', 'readwrite', (store) => {
      store.put(profile, 'doctor_profile');
    });
    notifyDataChanged();
    return res;
  },

  // NOTES (Lightweight thoughts)
  async getNotes() {
    return performTx('notes', 'readonly', (store) => {
      return new Promise((resolve) => {
        const req = store.getAll();
        req.onsuccess = () => {
          const notes = req.result || [];
          notes.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
          resolve(notes);
        };
        req.onerror = () => reject(req.error || new Error('Could not read workspace notes.'));
      });
    });
  },  async addNote(note) {
    const res = await performTx('notes', 'readwrite', (store) => {
      store.put(note);
    });
    notifyDataChanged();
    return res;
  },

  async updateNote(note) {
    const res = await performTx('notes', 'readwrite', (store) => {
      store.put(note);
    });
    notifyDataChanged();
    return res;
  },

  async deleteNote(id) {
    const res = await performTx('notes', 'readwrite', (store) => {
      store.delete(id);
    });
    notifyDataChanged();
    return res;
  },

  // INSIGHTS (Core clinical ideas)
  async getInsights() {
    return performTx('insights', 'readonly', (store) => {
      return new Promise((resolve) => {
        const req = store.getAll();
        req.onsuccess = () => {
          const items = req.result || [];
          items.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
          resolve(items);
        };
      });
    });
  },

  async getInsight(id) {
    return performTx('insights', 'readonly', (store) => {
      return new Promise((resolve) => {
        const req = store.get(id);
        req.onsuccess = () => resolve(req.result || null);
      });
    });
  },

  async saveInsight(insight) {
    const res = await performTx('insights', 'readwrite', (store) => {
      store.put(insight);
    });
    notifyDataChanged();
    return res;
  },

  async deleteInsight(id) {
    // Delete insight and associated scripts
    await performTx('insights', 'readwrite', (store) => {
      store.delete(id);
    });
    const scripts = await this.getScriptsByInsight(id);
    for (const s of scripts) {
      await this.deleteScript(s.id);
    }
    notifyDataChanged();
  },

  // SCRIPTS (Flashcard review queue)
  async getScripts() {
    return performTx('scripts', 'readonly', (store) => {
      return new Promise((resolve) => {
        const req = store.getAll();
        req.onsuccess = () => resolve(req.result || []);
      });
    });
  },

  async getScriptsByInsight(insightId) {
    return performTx('scripts', 'readonly', (store) => {
      return new Promise((resolve) => {
        const index = store.index('by_insight');
        const req = index.getAll(insightId);
        req.onsuccess = () => resolve(req.result || []);
      });
    });
  },

  async getPendingReviewScripts() {
    return performTx('scripts', 'readonly', (store) => {
      return new Promise((resolve) => {
        const index = store.index('by_status');
        const req = index.getAll('pending_review');
        req.onsuccess = () => {
          const scripts = req.result || [];
          resolve(scripts);
        };
      });
    });
  },

  async saveScript(script) {
    const res = await performTx('scripts', 'readwrite', (store) => {
      store.put(script);
    });
    notifyDataChanged();
    return res;
  },

  async saveScripts(scriptsArray) {
    const database = await openDatabase();
    const res = await new Promise((resolve, reject) => {
      const tx = database.transaction('scripts', 'readwrite');
      const store = tx.objectStore('scripts');
      scriptsArray.forEach((script) => store.put(script));
      tx.oncomplete = () => resolve(true);
      tx.onerror = (e) => reject(e.target.error);
    });
    notifyDataChanged();
    return res;
  },

  async updateScript(script) {
    const res = await performTx('scripts', 'readwrite', (store) => {
      store.put(script);
    });
    notifyDataChanged();
    return res;
  },

  async deleteScript(id) {
    const res = await performTx('scripts', 'readwrite', (store) => {
      store.delete(id);
    });
    notifyDataChanged();
    return res;
  },

  // SCHEDULED REELS (Trial Reels & Main Reels on Calendar)
  async getScheduledReels() {
    return performTx('scheduled_reels', 'readonly', (store) => {
      return new Promise((resolve) => {
        const req = store.getAll();
        req.onsuccess = () => {
          const items = req.result || [];
          items.sort((a, b) => new Date(a.scheduled_date) - new Date(a.scheduled_date));
          resolve(items);
        };
      });
    });
  },

  async getScheduledReel(id) {
    return performTx('scheduled_reels', 'readonly', (store) => {
      return new Promise((resolve) => {
        const req = store.get(id);
        req.onsuccess = () => resolve(req.result || null);
      });
    });
  },

  async saveScheduledReel(reel) {
    const res = await performTx('scheduled_reels', 'readwrite', (store) => {
      store.put(reel);
    });
    notifyDataChanged();
    return res;
  },

  async saveScheduledReels(reelsArray) {
    const database = await openDatabase();
    const res = await new Promise((resolve, reject) => {
      const tx = database.transaction('scheduled_reels', 'readwrite');
      const store = tx.objectStore('scheduled_reels');
      reelsArray.forEach((reel) => store.put(reel));
      tx.oncomplete = () => resolve(true);
      tx.onerror = (e) => reject(e.target.error);
    });
    notifyDataChanged();
    return res;
  },

  async updateScheduledReel(reel) {
    const res = await performTx('scheduled_reels', 'readwrite', (store) => {
      store.put(reel);
    });
    notifyDataChanged();
    return res;
  },

  async deleteScheduledReel(id) {
    const res = await performTx('scheduled_reels', 'readwrite', (store) => {
      store.delete(id);
    });
    notifyDataChanged();
    return res;
  },

  // FULL EXPORT & IMPORT (Zero-loss JSON Backup)
  async exportFullDatabase() {
    const profile = await this.getProfile();
    const notes = await this.getNotes();
    const insights = await this.getInsights();
    const scripts = await this.getScripts();
    const scheduledReels = await this.getScheduledReels();
    const ideaMateIdeas = JSON.parse(localStorage.getItem('ideaBank_ideas') || '[]');

    return {
      appName: 'Content Mate',
      exportedAt: new Date().toISOString(),
      version: 1,
      profile,
      notes,
      insights,
      scripts,
      scheduledReels,
      ideaMateIdeas
    };
  },

  async importFullDatabase(data) {
    if (!data || !data.version) {
      throw new Error('Invalid backup file format');
    }

    if (data.profile) await this.saveProfile(data.profile);
    if (Array.isArray(data.ideaMateIdeas)) localStorage.setItem('ideaBank_ideas', JSON.stringify(data.ideaMateIdeas));
    
    // Clear and restore notes
    if (Array.isArray(data.notes)) {
      for (const n of data.notes) await this.addNote(n);
    }

    // Clear and restore insights
    if (Array.isArray(data.insights)) {
      for (const i of data.insights) await this.saveInsight(i);
    }

    // Clear and restore scripts
    if (Array.isArray(data.scripts)) {
      await this.saveScripts(data.scripts);
    }

    // Clear and restore scheduled reels
    if (Array.isArray(data.scheduledReels)) {
      await this.saveScheduledReels(data.scheduledReels);
    }

    return true;
  },

  async resetAllData() {
    const database = await openDatabase();
    const stores = ['profile', 'notes', 'insights', 'scripts', 'scheduled_reels'];
    for (const storeName of stores) {
      await new Promise((resolve, reject) => {
        const tx = database.transaction(storeName, 'readwrite');
        const store = tx.objectStore(storeName);
        store.clear();
        tx.oncomplete = () => resolve();
        tx.onerror = (e) => reject(e.target.error);
      });
    }
    // Clear localStorage
    localStorage.clear();

    // A reset returns to first-run onboarding with a clean workspace.
    await this.saveProfile({
      name: '',
      specialty: '',
      audience: 'Patients',
      language: 'English',
      tone: 'Conversational & Empathetic',
      cta: 'both',
      postingDays: ['Mon', 'Wed', 'Fri'],
      onboarded: false,
      tutorialSeen: false
    });
  },

  async clearAll() {
    return this.resetAllData();
  }
};

/* js/webdav.js */
const KEY = 'contentmate.webdav.settings';
function getWebDavSettings() { try { return { remoteFile: 'contentmate-backup.json', ...JSON.parse(localStorage.getItem(KEY) || '{}') }; } catch (_) { return { remoteFile: 'contentmate-backup.json' }; } }
function saveWebDavSettings(value) { const next = { ...getWebDavSettings(), ...value }; localStorage.setItem(KEY, JSON.stringify(next)); return next; }
function directoryUrl(s) { const base = String(s.url || '').trim().replace(/\/+$/, ''); if (!base) throw new Error('Enter the WebDAV URL.'); return base; }
function url(s) { const base = directoryUrl(s); const file = String(s.remoteFile || s.filename || 'contentmate-backup.json').trim().replace(/^\/+/, ''); return `${base}/${file.split('/').map(encodeURIComponent).join('/')}`; }
async function request(s, method, body, target = url(s)) { if (!s.username || !s.password) throw new Error('Enter the WebDAV username and app password.'); try { const proxy = typeof location !== 'undefined' && location.protocol !== 'file:'; const response = await fetch(proxy ? '/api/webdav' : target, { method: proxy ? 'POST' : method, headers: proxy ? { 'Content-Type': 'application/json' } : { Authorization: `Basic ${btoa(`${s.username}:${s.password}`)}`, ...(method === 'PROPFIND' ? { Depth: '1' } : {}), ...(body ? { 'Content-Type': 'application/json; charset=utf-8' } : {}) }, body: proxy ? JSON.stringify({ url: target, username: s.username, password: s.password, method, body }) : body, cache: 'no-store' }); if (!response.ok) throw new Error(`WebDAV ${method} failed (${response.status}).`); return response; } catch (e) { if (e instanceof TypeError) throw new Error('Could not reach WebDAV. For local file mode, start server.py and open http://127.0.0.1:8765.'); throw e; } }
async function pushDatabase(s, backup) { await request(s, 'PUT', JSON.stringify(backup, null, 2)); }
async function pullDatabase(s) { const data = await (await request(s, 'GET')).json().catch(() => null); if (!data || !data.version) throw new Error('The remote file is not a valid Content Mate backup.'); return data; }
async function testWebDav(s) { await request(s, 'PROPFIND', null, directoryUrl(s)); }

// Public facade used by the app shell and Settings. WebDAV is optional: all
// callers only touch this facade when sync is explicitly configured.
const WebDAVClient = {
  getConfig() { return getWebDavSettings(); },
  isConfigured() { const s = getWebDavSettings(); return Boolean(s.url && s.username && s.password); },
  saveConfig(value) { return saveWebDavSettings({ ...value, remoteFile: value.remoteFile || value.filename }); },
  clearConfig() { localStorage.removeItem(KEY); window.dispatchEvent(new CustomEvent('contentmate-webdav-status-change')); },
  async testConnection(config = getWebDavSettings()) { await testWebDav(config); return { message: 'Successfully connected to WebDAV server.' }; },
  async pushToCloud() { await pushDatabase(getWebDavSettings(), await db.exportFullDatabase()); return { message: 'Workspace uploaded successfully.' }; },
  async pullFromCloud() { const backup = await pullDatabase(getWebDavSettings()); await db.resetAllData(); await db.importFullDatabase(backup); return { found: true, message: 'Workspace downloaded successfully.' }; },
  async syncNow() { await this.pushToCloud(); return { action: 'pushed', message: 'Workspace synced successfully.' }; },
  scheduleAutoPush() {
    const config = getWebDavSettings();
    if (config.autoSync && this.isConfigured()) this.pushToCloud().catch((error) => console.warn('[WebDAV auto-sync]', error.message));
  }
};

