/* js/utils.js */
/**
 * Content OS for Doctors — Utility Helpers
 */

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

function formatDate(dateString) {
  if (!dateString) return '';
  const d = new Date(dateString);
  if (isNaN(d.getTime())) return dateString;

  return d.toLocaleDateString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric'
  });
}

function formatFullDate(dateString) {
  if (!dateString) return '';
  const d = new Date(dateString);
  if (isNaN(d.getTime())) return dateString;

  return d.toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    year: 'numeric'
  });
}

function formatDateForInput(dateOrString) {
  if (!dateOrString) return '';
  const d = new Date(dateOrString);
  if (isNaN(d.getTime())) return '';

  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function addDays(dateOrString, days) {
  const d = new Date(dateOrString);
  d.setDate(d.getDate() + days);
  return d.toISOString();
}

function getDaysDifference(dateA, dateB) {
  const a = new Date(dateA);
  const b = new Date(dateB);
  const diffTime = b.getTime() - a.getTime();
  return Math.floor(diffTime / (1000 * 60 * 60 * 24));
}

function formatRelativeDate(isoDate) {
  if (!isoDate) return '';
  const now = new Date();
  const d = new Date(isoDate);
  const diffMs = now - d;
  const diffSec = Math.floor(diffMs / 1000);
  const diffMin = Math.floor(diffSec / 60);
  const diffHour = Math.floor(diffMin / 60);
  const diffDay = Math.floor(diffHour / 24);

  if (diffDay > 14) {
    return formatDate(isoDate);
  } else if (diffDay >= 2) {
    return `${diffDay} days ago`;
  } else if (diffDay === 1) {
    return 'Yesterday';
  } else if (diffHour >= 1) {
    return `${diffHour}h ago`;
  } else if (diffMin >= 1) {
    return `${diffMin}m ago`;
  } else {
    return 'Just now';
  }
}

async function copyToClipboard(text) {
  if (!navigator.clipboard) {
    // Fallback for older contexts
    const textArea = document.createElement('textarea');
    textArea.value = text;
    textArea.style.position = 'fixed';
    textArea.style.opacity = '0';
    document.body.appendChild(textArea);
    textArea.select();
    try {
      document.execCommand('copy');
      document.body.removeChild(textArea);
      showToast('Copied to clipboard!', 'success');
      return true;
    } catch (err) {
      document.body.removeChild(textArea);
      showToast('Copy failed. Please manually select.', 'error');
      return false;
    }
  }

  try {
    await navigator.clipboard.writeText(text);
    showToast('Prompt copied. Paste it into any AI, then copy its complete response back here.', 'success');
    return true;
  } catch (err) {
    console.error('Clipboard error:', err);
    showToast('Failed to copy. Please manually copy.', 'error');
    return false;
  }
}

function showToast(message, type = 'success', duration = 3200) {
  const container = document.getElementById('toast-container');
  if (!container) return;

  const toast = document.createElement('div');
  toast.className = `toast toast-${type}`;

  let icon = '';
  if (type === 'success') {
    icon = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#34C759" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>`;
  } else if (type === 'error') {
    icon = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#FF3B30" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>`;
  } else {
    icon = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#007AFF" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>`;
  }

  toast.innerHTML = `
    <span>${icon}</span>
    <span>${escapeHtml(message)}</span>
  `;

  container.appendChild(toast);

  // Vibration for tactile feel if supported
  if (navigator.vibrate) {
    navigator.vibrate(20);
  }

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(-10px)';
    toast.style.transition = 'all 200ms ease';
    setTimeout(() => {
      if (toast.parentNode) toast.parentNode.removeChild(toast);
    }, 200);
  }, duration);
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function truncateText(str, maxLen = 80) {
  if (!str) return '';
  if (str.length <= maxLen) return str;
  return str.substring(0, maxLen).trim() + '...';
}

// Simulated Time Travel Helpers (Testing)
let systemTimeOffsetDays = parseInt(localStorage.getItem('doctor_os_time_offset_days') || '0', 10);

function getSystemDate() {
  const d = new Date();
  if (systemTimeOffsetDays !== 0) {
    d.setDate(d.getDate() + systemTimeOffsetDays);
  }
  return d;
}

function getTimeShiftDays() {
  return systemTimeOffsetDays;
}

function setTimeShiftDays(days) {
  systemTimeOffsetDays = days;
  localStorage.setItem('doctor_os_time_offset_days', String(days));
  window.dispatchEvent(new Event('doctor-os-system-date-change'));
}

// Developer tools are intentionally session-only. They provide a light gate for
// demo/testing controls, not a security boundary for sensitive data.
const DEV_TOOLS_STORAGE_KEY = 'doctor_os_dev_tools_enabled';

function getDevToolsEnabled() {
  return sessionStorage.getItem(DEV_TOOLS_STORAGE_KEY) === 'true';
}

function setDevToolsEnabled(enabled) {
  if (enabled) {
    sessionStorage.setItem(DEV_TOOLS_STORAGE_KEY, 'true');
  } else {
    sessionStorage.removeItem(DEV_TOOLS_STORAGE_KEY);
  }
  window.dispatchEvent(new CustomEvent('doctor-os-dev-tools-change', { detail: { enabled } }));
}

/* js/ideamate.js */
// Shared local bridge for the standalone IdeaMate idea bank.
function syncInsightToIdeaMate(insight, source = 'content-mate') {
  if (!insight?.id || !insight.title) return;
  const key = 'ideaBank_ideas';
  const ideas = JSON.parse(localStorage.getItem(key) || '[]');
  const existing = ideas.find((idea) => idea.externalId === insight.id || idea.id === `cm_${insight.id}`);
  const idea = { id: existing?.id || `cm_${insight.id}`, externalId: insight.id, title: insight.title, description: insight.description || insight.supporting_points || '', evidence: insight.supporting_points || '', notes: insight.references || '', category: insight.category || existing?.category || 'Clinical insights', subcategory: insight.subcategory || existing?.subcategory || (source === 'ideamate' ? 'IdeaMate' : 'Content Mate'), status: existing?.status || 'fresh', createdAt: existing?.createdAt || insight.created_at || new Date().toISOString(), usedAt: existing?.usedAt || null, trashedAt: existing?.trashedAt || null, savedAt: existing?.savedAt || null, useNote: existing?.useNote || '', useCount: existing?.useCount || 0, isDefault: false, isUserCreated: true, source };
  const index = ideas.findIndex((item) => item.id === idea.id);
  if (index >= 0) ideas[index] = { ...ideas[index], ...idea }; else ideas.push(idea);
  localStorage.setItem(key, JSON.stringify(ideas));
}
function getIdeaMateIdeas() {
  const stored = JSON.parse(localStorage.getItem('ideaBank_ideas') || '[]').filter((idea) => !String(idea.id || '').startsWith('patient-content-'));
  const bundled = [
    ...(typeof DEFAULT_IDEAS !== 'undefined' && Array.isArray(DEFAULT_IDEAS) ? DEFAULT_IDEAS.map((idea, index) => ({ ...idea, id: idea.id || `clinic-growth-${index}`, status: idea.status || 'fresh', isDefault: true, isUserCreated: false })) : []),
    ...(typeof PATIENT_QUESTIONS !== 'undefined' && Array.isArray(PATIENT_QUESTIONS) ? PATIENT_QUESTIONS.map((idea, index) => ({ ...idea, id: idea.id || `patient-question-${index}`, status: idea.status || 'fresh', isDefault: true, isUserCreated: false })) : [])
  ];
  const merged = [...stored];
  bundled.forEach((idea) => { if (!merged.some((existing) => existing.id === idea.id || (existing.title === idea.title && existing.specialty === idea.specialty))) merged.push(idea); });
  if (merged.length !== stored.length) localStorage.setItem('ideaBank_ideas', JSON.stringify(merged));
  return merged;
}

